<script setup lang="ts">
import {ref,watch} from 'vue';import type {ViewModel} from '../app/useWorkspace';
const props=defineProps<{w:ViewModel}>();const chosen=ref('');watch(()=>props.w.formatErrors.entries[0]?.id,id=>{chosen.value=id||'';});
</script>
<template><section class="surface format-error-page"><header class="panel-heading"><div><p class="eyebrow">FORMAT / 返回记录</p><h1>格式错误文本</h1></div><button :disabled="!w.formatErrors.entries.length" @click="w.formatErrors.clear();chosen=''">清空记录</button></header><p class="muted">仅保存在当前浏览器，最多保留最近 100 条。显示模型内容返回，不含独立思考字段和请求提示词。</p><p v-if="w.formatErrors.problem" role="alert">{{w.formatErrors.problem}}</p><p v-if="!w.formatErrors.entries.length">暂无格式错误记录。</p><details v-for="(entry,i) in w.formatErrors.entries" :key="entry.id" :open="chosen?chosen===entry.id:i===0" @toggle="event=>{if((event.target as HTMLDetailsElement).open)chosen=entry.id}"><summary>{{new Date(entry.at).toLocaleString()}} · {{entry.code}}</summary><p class="muted">会话 {{entry.sessionId}} · 楼层 {{entry.turnId}}</p><pre v-if="chosen?chosen===entry.id:i===0">{{entry.raw}}</pre></details></section></template>
<style scoped>.format-error-page details{border-bottom:1px solid var(--color-border);padding:14px 0}.format-error-page summary{cursor:pointer;color:var(--color-accent)}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:60dvh;overflow:auto;font:13px/1.8 monospace}</style>
